import fs from 'node:fs';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {orangeryPage} from './src/orangery.mjs';
const data=JSON.parse(fs.readFileSync('content.json','utf8'));
const library=JSON.parse(fs.readFileSync('photo-library.json','utf8'));
const photoWidths=new Map([...library.photos,...Object.values(library.houses).flat()].map(([slug,,,small,large])=>[slug,[small,large]]));
const out='dist';fs.mkdirSync(out,{recursive:true});fs.mkdirSync(out+'/assets',{recursive:true});fs.copyFileSync('content.json',out+'/content.json');
const orangeryPhotos=[['orangery-reference',1280],['orangery-daylight',1672],['orangery-evening',1672],['orangery-table',1672]];
for(const [name,width] of orangeryPhotos){
 photoWidths.set(name,[720,width]);
 for(const variant of ['', '-small'])fs.copyFileSync(`media/orangery/${name}${variant}.webp`,`${out}/assets/${name}${variant}.webp`);
}
const reviewSlugs=['review-01','review-02','review-03','review-04','review-05','review-06','review-07','review-08'];
for(const name of reviewSlugs){
 for(const variant of ['', '-small'])fs.copyFileSync(`media/reviews/${name}${variant}.webp`,`${out}/assets/${name}${variant}.webp`);
}
fs.copyFileSync('src/orangery.css',out+'/orangery.css');
fs.copyFileSync('src/weddings.css',out+'/weddings.css');
fs.copyFileSync('src/app.js',out+'/app.js');
fs.copyFileSync('src/styles.css',out+'/styles.css');
const videoSlugs=['shalash','les','tuman','luna'];
const videoDurations={shalash:'1:26',les:'2:11',tuman:'0:55',luna:'0:58'};
const videoAttrs=h=>`data-video data-video-house="${h.slug}" data-video-src="/assets/house-${h.slug}.mp4?v=${mediaVersion[h.slug]}" data-video-poster="/assets/house-${h.slug}-poster.jpg?v=${posterVersion[h.slug]}" data-video-caption="Видеообзор дома ${esc(h.name)}"`;
for(const slug of videoSlugs){fs.copyFileSync(`media/house-${slug}.mp4`,`${out}/assets/house-${slug}.mp4`);fs.copyFileSync(`media/house-${slug}-poster.jpg`,`${out}/assets/house-${slug}-poster.jpg`);}
const posterVersion=Object.fromEntries(videoSlugs.map(slug=>[slug,createHash('sha256').update(fs.readFileSync(`media/house-${slug}-poster.jpg`)).digest('hex').slice(0,10)]));
const heroVersion={};
for(const name of ['hero-wide.mp4','hero-mobile.mp4','hero-poster.jpg']){
 fs.copyFileSync(`media/${name}`,`${out}/assets/${name}`);
 heroVersion[name]=createHash('sha256').update(fs.readFileSync(`media/${name}`)).digest('hex').slice(0,10);
}
const cardVersion={};
for(const slug of videoSlugs){
 for(const variant of ['wide','mobile']){
  const name=`house-${slug}-preview-${variant}.mp4`;
  fs.copyFileSync(`media/${name}`,`${out}/assets/${name}`);
  cardVersion[name]=createHash('sha256').update(fs.readFileSync(`media/${name}`)).digest('hex').slice(0,10);
 }
}
const previewFile='forest-preview.mp4';
fs.copyFileSync('media/'+previewFile,out+'/assets/'+previewFile);
const previewSrc='/assets/'+previewFile+'?v='+createHash('sha256').update(fs.readFileSync('media/'+previewFile)).digest('hex').slice(0,10);
for(const name of ['les-wedding.mp4','les-wedding-poster.jpg'])fs.copyFileSync(`media/weddings/${name}`,`${out}/assets/${name}`);
const weddingVideoVersion=createHash('sha256').update(fs.readFileSync('media/weddings/les-wedding.mp4')).digest('hex').slice(0,10);
const weddingPosterVersion=createHash('sha256').update(fs.readFileSync('media/weddings/les-wedding-poster.jpg')).digest('hex').slice(0,10);
const mediaVersion=Object.fromEntries(videoSlugs.map(slug=>[slug,createHash('sha256').update(fs.readFileSync(`media/house-${slug}.mp4`)).digest('hex').slice(0,10)]));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const i=(name,cls='')=>`<svg class="icon ${cls}" aria-hidden="true"><use href="/assets/icons.svg#${name}"></use></svg>`;
const iconNames=['arrow-up-right','arrow-right','arrow-left','chevron-left','chevron-right','plus','minus','x','menu-2','phone','brand-telegram','brand-whatsapp','brand-instagram','brand-vk','message-circle','map-pin','player-play','player-pause','calendar','users','flame','trees','check','copy','sun','moon','download','photo','shield-check','coffee','bath','home','armchair','sofa','bed','clock','external-link'];
const symbols=iconNames.map(n=>{const p=`node_modules/@tabler/icons/icons/outline/${n}.svg`;if(!fs.existsSync(p))throw new Error(p);return fs.readFileSync(p,'utf8').replace(/<svg[^>]*>/,`<symbol id="${n}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">`).replace('</svg>','</symbol>');}).join('');
fs.writeFileSync(out+'/assets/icons.svg',`<svg xmlns="http://www.w3.org/2000/svg">${symbols}</svg>`);
const photo=(name,alt,cls='',eager=false,sizes='(max-width: 767px) 100vw, 60vw')=>{
 const [small,large]=photoWidths.get(name)||[700,1800];
 const srcset=small<large?`/assets/${name}-small.webp ${small}w, /assets/${name}.webp ${large}w`:`/assets/${name}.webp ${large}w`;
 return `<img class="${cls}" src="/assets/${name}.webp" srcset="${srcset}" sizes="${sizes}" alt="${esc(alt)}" loading="${eager?'eager':'lazy'}" ${eager?'fetchpriority="high"':''} decoding="async">`;
};
const c=data.contacts;
const btn=(text,attrs='',type='primary')=>`<button class="button ${type}" ${attrs}>${text}${i('arrow-up-right')}</button>`;
const book=(text='Уточнить свободные даты',house='',reason='Отдых')=>btn(text,`data-book data-house="${esc(house)}" data-reason="${esc(reason)}"`);
const link=(text,href,type='text-link')=>`<a class="${type}" href="${href}">${text}${i('arrow-up-right')}</a>`;
const nav=[['Домики','/houses/'],['Бани и чаны','/services/'],['Мероприятия','/events/'],['Галерея','/gallery/'],['О комплексе','/about/'],['Контакты','/contacts/']];
const header=(active,venue='')=>`<a class="skip" href="#main">Перейти к содержимому</a><header class="header"><a class="logo" href="/" aria-label="Лес Сургут, на главную"><img src="/assets/logo.png" alt="LES SURGUT" width="100" height="60"></a><nav class="desktop-nav" aria-label="Главная навигация">${nav.map(([n,h])=>`<a href="${h}" ${active===h?'aria-current="page"':''}>${n}</a>`).join('')}</nav><div class="header-actions"><a class="header-phone" href="tel:${c.phoneRaw}">${i('phone')}<span>${c.phone}</span></a><button class="header-book" data-book ${venue?'data-house="orangery" data-reason="Оранжерея"':''}>${venue?'Обсудить событие':'Выбрать даты'}${i('arrow-up-right')}</button><button class="menu-toggle icon-button" aria-label="Открыть меню" aria-expanded="false" aria-controls="mobile-menu">${i('menu-2')}</button></div></header><dialog id="mobile-menu" class="mobile-menu" aria-label="Меню сайта"><div class="mobile-menu-shell">
 <div class="mobile-menu-top"><a class="mobile-menu-logo" href="/" aria-label="Лес Сургут, на главную"><img src="/assets/logo.png" alt="LES SURGUT"></a><button type="button" class="mobile-menu-close" data-menu-close>Закрыть ${i('x')}</button></div>
 <p class="mobile-menu-caption">Загородный комплекс · Сургут</p><nav class="mobile-menu-links" aria-label="Мобильная навигация">${[...nav,['Оранжерея','/orangery/'],['Отдых в будни','/offers/']].map(([name,href])=>`<a href="${href}" ${active===href?'aria-current="page"':''}><span>${name}</span>${i('arrow-up-right')}</a>`).join('')}</nav>
 <button type="button" class="mobile-menu-book" data-book ${venue?'data-house="orangery" data-reason="Оранжерея"':''}>${venue?'Обсудить Оранжерею':'Спланировать отдых'} ${i('arrow-right')}</button>
 <div class="mobile-menu-contact"><img src="/assets/24-pines-sky-small.webp" alt="Сосны в комплексе «Лес»"><div><p>Загородный комплекс в Сургуте</p><a class="mobile-menu-phone" href="tel:${c.phoneRaw}">${c.phone}</a><span>15 минут от города</span></div></div>
 <div class="mobile-menu-messengers"><a data-channel="max" href="${c.max}" target="_blank" rel="noopener">MAX ${i('arrow-up-right')}</a><a data-channel="telegram" href="${c.telegram}" target="_blank" rel="noopener">Telegram ${i('arrow-up-right')}</a><a data-channel="whatsapp" href="https://wa.me/${c.whatsapp}" target="_blank" rel="noopener">WhatsApp ${i('arrow-up-right')}</a></div>
 </div></dialog>`;
const socials=()=>`<div class="socials"><a data-channel="max" href="${c.max}" target="_blank" rel="noopener" aria-label="Написать в MAX">MAX${i('arrow-up-right')}</a><a data-channel="telegram" href="${c.telegram}" target="_blank" rel="noopener">Telegram${i('brand-telegram')}</a><a data-channel="whatsapp" href="https://wa.me/${c.whatsapp}" target="_blank" rel="noopener">WhatsApp${i('brand-whatsapp')}</a></div>`;
const footer=(venue='')=>`<footer class="footer"><div class="footer-main"><a class="footer-logo" href="/"><img src="/assets/logo.png" alt="LES SURGUT" width="148" height="88"></a><div class="footer-place"><p>Загородный комплекс отдыха</p><p>Сосновый лес. Река. Ваши близкие.</p><a href="tel:${c.phoneRaw}">${c.phone}</a></div><div class="footer-nav">${nav.map(([n,h])=>`<a href="${h}">${n}</a>`).join('')}<a href="/orangery/">Оранжерея · скоро</a></div><div class="footer-social">${socials()}<a href="${c.channel}" target="_blank" rel="noopener">Наш Telegram-канал ${i('arrow-up-right')}</a><a href="${c.instagram}" target="_blank" rel="noopener">Instagram ${i('brand-instagram')}</a></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Лес, Сургут</span><a href="/privacy/">Конфиденциальность</a><button class="link-button" data-cookie-settings>Настройки файлов cookie</button><a href="${c.map}" target="_blank" rel="noopener">Ягодная улица ${i('map-pin')}</a></div></footer><div class="mobile-bottom"><button data-book ${venue?'data-house="orangery" data-reason="Оранжерея"':''}>${i(venue?'message-circle':'calendar')}${venue?'Обсудить событие':'Выбрать даты'}</button><a href="tel:${c.phoneRaw}">${i('phone')}Позвонить</a></div>`;
const dialogs=()=>`<dialog id="booking-dialog" class="booking-dialog" aria-labelledby="booking-title" aria-describedby="booking-description">
 <div class="dialog-shell booking-shell">
  <div class="booking-mobile-brand"><img src="/assets/logo.png" alt="LES SURGUT"></div>
  <button class="dialog-close icon-button" data-close aria-label="Закрыть форму"><span class="booking-close-label">Закрыть</span>${i('x')}</button>
  <aside class="booking-aside">
   <img id="booking-aside-photo" loading="lazy" src="/assets/tg-303972.webp" alt="Река и сосны в загородном комплексе «Лес»" decoding="async">
   <div class="booking-aside-wash"></div>
   <div class="booking-aside-brand"><img src="/assets/logo.png" alt="LES SURGUT"><span>15 минут от города</span></div>
   <div class="booking-aside-copy"><span>ВАШЕ ВРЕМЯ. В «ЛЕСУ».</span><h3 id="booking-aside-title">Ближе к природе.<br>Ближе к своим.</h3><p id="booking-aside-caption">Четыре дома среди сосен. Поможем найти тот, в котором вам будет хорошо.</p></div>
  </aside>
  <div class="booking-panel" data-booking-scroll>
   <ol class="booking-steps" aria-label="Шаги заявки"><li class="is-current" data-booking-step-label="0" aria-current="step"><span>01</span>Ваш отдых</li><li data-booking-step-label="1"><span>02</span>Контакты</li></ol>
   <header class="booking-intro"><h2 id="booking-title"><span data-booking-title-wide>Спланируем ваш отдых.</span><span data-booking-title-mobile>Ваш отдых</span></h2><p id="booking-description">Выберите дом и даты. О деталях позаботимся вместе.</p></header>
   <form id="booking-form" novalidate>
    <section class="booking-step" data-booking-step="0" aria-label="Дом, даты и гости">
     <label class="booking-field booking-house-field"><span>Дом или площадка</span><span class="booking-select-wrap"><img class="booking-house-thumb" id="booking-house-thumb" src="/assets/tg-303972-small.webp" alt=""><select name="house" id="booking-house"><option value="">Помогите выбрать</option>${data.houses.map(h=>`<option value="${h.slug}">${h.name}</option>`).join('')}<option value="all">Весь комплекс</option><option value="orangery">Оранжерея · скоро</option></select>${i('chevron-right')}</span></label>
     <fieldset class="booking-format"><legend>Как хотите отдохнуть?</legend><div class="booking-format-options"><label><input type="radio" name="bookingType" value="stay" checked><span>${i('home')}Отдых в доме</span></label><label><input type="radio" name="bookingType" value="event"><span>${i('users')}Мероприятие</span></label></div></fieldset>
     <div class="booking-dates"><label class="booking-field"><span data-booking-date-start>Заезд</span><input type="date" name="arrival" required></label><label class="booking-field"><span data-booking-date-end>Выезд</span><input type="date" name="departure" required></label></div>
     <p class="booking-dates-note" id="booking-dates-note">Менеджер подтвердит свободные даты.</p>
     <div class="booking-guests"><div><label for="booking-guests">Гости</label><p id="guests-help">Подберём размещение под вашу компанию.</p></div><div class="guest-control"><button type="button" class="guest-step" data-guest-step="-1" aria-label="Уменьшить количество гостей">${i('minus')}</button><input id="booking-guests" name="guests" type="text" value="2" required inputmode="numeric" pattern="[0-9]*" aria-describedby="guests-help guests-error"><button type="button" class="guest-step" data-guest-step="1" aria-label="Увеличить количество гостей">${i('plus')}</button></div></div>
     <p id="guests-error" class="field-error" role="alert"></p>
     <button class="button primary booking-next" type="button" data-booking-next><span class="booking-next-wide">Далее к контактам</span><span class="booking-next-mobile">Продолжить</span> ${i('arrow-right')}</button>
     <p class="booking-step-note">Можно обсудить детали в удобном мессенджере.</p>
    </section>
    <section class="booking-step" data-booking-step="1" aria-label="Контакты и пожелания" hidden>
     <div class="booking-summary" aria-label="Ваш выбор"><span id="booking-summary-house">Поможем выбрать дом</span><span id="booking-summary-dates">Даты уточним</span><span id="booking-summary-guests">2 гостя</span></div>
     <div class="booking-contacts"><label class="booking-field"><span>Ваше имя</span><input name="name" autocomplete="given-name" maxlength="60" placeholder="Как к вам обращаться" required></label><label class="booking-field"><span>Телефон</span><input name="phone" type="tel" autocomplete="tel" inputmode="tel" placeholder="+7 (999) 999-99-99" required maxlength="18" aria-describedby="phone-error"></label></div>
     <p id="phone-error" class="field-error" role="alert"></p>
     <fieldset class="channel-picker"><legend>Где удобнее общаться?</legend><label><input type="radio" name="channel" value="max" checked><span><b class="channel-mark">M</b>MAX</span></label><label><input type="radio" name="channel" value="whatsapp"><span>${i('brand-whatsapp')}WhatsApp</span></label><label><input type="radio" name="channel" value="telegram"><span>${i('brand-telegram')}Telegram</span></label></fieldset>
     <details class="booking-wishes-disclosure" open><summary><span>Добавить пожелания</span>${i('plus')}</summary><label class="booking-field booking-wishes"><span class="booking-sr-only">Пожелания к отдыху</span><textarea name="comment" rows="2" maxlength="600" placeholder="Баня, чан, праздник или ваши пожелания"></textarea></label></details>
     <label class="booking-trap" aria-hidden="true">Компания<input name="company" tabindex="-1" autocomplete="off"></label><input type="hidden" name="startedAt" value="">
     <div id="booking-turnstile" class="booking-turnstile" hidden></div><p id="booking-security-note" class="booking-security-note" role="status">Заявка защищена от спама Cloudflare Turnstile.</p>
     <label class="checkbox"><input type="checkbox" required name="consent"><span>Согласен на передачу данных менеджеру комплекса. <a href="/privacy/" target="_blank" rel="noopener">Политика конфиденциальности</a></span></label>
     <div class="booking-actions"><button type="button" class="booking-back" data-booking-back>${i('arrow-left')}Назад</button><button class="button primary submit" type="submit">Отправить заявку ${i('arrow-up-right')}</button></div>
     <p class="booking-step-note">Бронирование подтвердит менеджер в переписке.</p>
    </section>
    <p id="form-error" class="form-error" role="alert"></p>
   </form>
   <section id="message-ready" hidden><span class="booking-ready-mark">${i('check')}</span><h3>Осталось отправить.</h3><p class="message-instruction">Скопируйте текст, затем откройте чат и отправьте его менеджеру.</p><textarea id="message-preview" rows="7" readonly aria-label="Текст сообщения менеджеру"></textarea><div class="ready-actions"><button class="button secondary" id="copy-message">Скопировать ${i('copy')}</button><a class="button primary" id="open-messenger" target="_blank" rel="noopener">Открыть чат ${i('arrow-up-right')}</a></div><p class="form-note" id="copy-status" role="status">Сообщение ещё не отправлено. Отправьте его в мессенджере.</p><button class="booking-back" id="edit-message">${i('arrow-left')}Изменить данные</button></section>
  </div>
 </div>
</dialog><dialog id="media-dialog" class="media-dialog" aria-label="Просмотр фото и видео"><button class="dialog-close icon-button" data-close aria-label="Закрыть просмотр">${i('x')}</button><button class="media-prev icon-button" aria-label="Предыдущее фото">${i('chevron-left')}</button><div class="media-stage"></div><button class="media-next icon-button" aria-label="Следующее фото">${i('chevron-right')}</button><p class="media-caption" aria-live="polite"></p></dialog><section class="cookie-banner" aria-label="Настройки cookie" hidden><div><strong>Только нужное для вашего отдыха</strong><p>Подключить карту и аналитику?</p></div><button class="button primary small" data-consent="all">Разрешить</button><button class="button secondary small" data-consent="essential">Только необходимые</button></section><div class="toast" role="status" hidden></div>`;
const price=h=>h.priceWeekday?`от ${new Intl.NumberFormat('ru-RU').format(h.priceWeekday)} ₽<span> / сутки</span>`:'Стоимость по запросу';
const sleeping=(h,compact=false)=>`<div class="sleeping${compact?' sleeping-compact':''}" aria-label="Спальные места">${(h.sleeping||[]).map(s=>`<span>${i(s.type)}${esc(s.label)}</span>`).join('')}</div>`;
const signature=(block,extra='')=>block?`<section class="house-signature wrap section-space reveal ${extra}"><div><span class="eyebrow">${esc(block.eyebrow)}</span><h2>${esc(block.title)}</h2><p>${esc(block.text)}</p></div><ul>${(block.items||[]).map(item=>`<li>${i('check')}<span>${esc(item)}</span></li>`).join('')}</ul></section>`:'';
const amenities=h=>`<section class="house-features wrap section-space"><div class="section-heading"><span class="eyebrow">ВСЁ ДЛЯ ОТДЫХА</span><h2>Удобства дома</h2></div><div class="house-comfort-grid" data-gallery-group>${(library.houses[h.slug]||[]).map(([name,caption])=>`<figure>${galleryButton(name,caption,'','','(max-width: 767px) 45vw, 24vw')}<figcaption>${esc(caption)}</figcaption></figure>`).join('')}</div><div class="amenity-groups">${(h.amenityGroups||[{title:'Для вашего комфорта',items:h.features||[]}]).map(group=>`<article><h3>${esc(group.title)}</h3><ul>${group.items.map(item=>`<li>${i('check')}<span>${esc(item)}</span></li>`).join('')}</ul></article>`).join('')}</div></section>`;
const eventGuidance=()=>`<aside class="event-guidance wrap reveal"><div>${i('users')}<div><h2>Планируете праздник или большую компанию?</h2><p>Количество гостей и варианты рассадки зависят от выбранного дома и формата мероприятия. Мы поможем подобрать комфортное решение.</p></div></div>${book('Обсудить мероприятие','','Мероприятие')}</aside>`;
const houseCard=(h,idx=0)=>`<article class="house-card reveal">
 <div class="house-card-media" data-card-preview>
  <a href="/houses/${h.slug}/" class="house-photo">
   ${photo(h.cover,`${h.name}: ${h.style}`)}
   <video class="house-background-film" muted playsinline loop preload="none" data-card-film data-wide-src="/assets/house-${h.slug}-preview-wide.mp4?v=${cardVersion[`house-${h.slug}-preview-wide.mp4`]}" data-mobile-src="/assets/house-${h.slug}-preview-mobile.mp4?v=${cardVersion[`house-${h.slug}-preview-mobile.mp4`]}" tabindex="-1" aria-hidden="true"></video>
   <span class="house-card-shade"></span><div class="house-card-caption"><div class="house-meta"><span>${esc(h.style)}</span></div><div class="house-title"><h3>${esc(h.name)}</h3><p data-price="${h.slug}">${price(h)}</p></div></div><span class="round-arrow">${i('arrow-up-right')}</span>
  </a>
  <button class="house-card-video" ${videoAttrs(h)} aria-label="Смотреть видеообзор дома ${esc(h.name)}">${i('player-play')}<span>Смотреть со звуком</span><span>${videoDurations[h.slug]}</span></button>
  <button class="house-card-pause icon-button" data-card-pause aria-label="Приостановить видео дома ${esc(h.name)}" aria-pressed="false">${i('player-pause')}</button>
 </div>
 <div class="house-card-content">${sleeping(h,true)}<p class="house-description">${esc(h.description)}</p><div class="house-card-actions"><button class="text-link" data-book data-house="${h.slug}">Уточнить даты ${i('arrow-up-right')}</button><a class="house-details-link" href="/houses/${h.slug}/">Подробнее о доме</a></div></div>
</article>`;
const houseGrid=()=>`<div class="houses-grid">${data.houses.map(houseCard).join('')}</div>`;
